import { EntityCompiler } from '@studnicky/entity/node';
export namespace ContextLookupEntity {
  export const Schema = {
    additionalProperties: false,
    properties: { found: { type: 'boolean' }, value: {} },
    required: ['found', 'value'],
    type: 'object'
  } as const;
  export type Type = { found: boolean; value: unknown };
  export function validate(candidate: unknown): candidate is Type {
    return typeof (candidate as Record<string, unknown>).found === 'boolean';
  }
  export const intake = EntityCompiler.compileIntake<Type>(Schema);
  export const create = EntityCompiler.compileCreate<Type>(Schema);
}

import { EntityCompiler } from '@studnicky/entity/node';
export namespace ValidatedAdaptiveConfigEntity {
  export const Schema = {
    anyOf: [
      { properties: { enabled: { const: false } } },
      { properties: { enabled: { const: true }, targetLatencyMs: { exclusiveMinimum: 0, type: 'number' } } }
    ],
    properties: { targetLatencyMs: { minimum: 0, type: 'number' } },
    required: ['enabled', 'targetLatencyMs']
  } as const;
  export type Type = { targetLatencyMs: number } & ({ enabled: false } | { enabled: true });
  export function validate(candidate: unknown): candidate is Type {
    return typeof (candidate as Record<string, unknown>).enabled === 'boolean';
  }
  export const intake = EntityCompiler.compileIntake<Type>(Schema);
}

